-- Adds personal-profile fields to the existing auth-linked profiles table.
alter table public.profiles add column if not exists employee_code text unique, add column if not exists personal_email text, add column if not exists date_of_birth date, add column if not exists gender text check(gender is null or gender in ('female','male','non_binary','prefer_not_to_say')), add column if not exists bank_details jsonb not null default '{}'::jsonb;
create index if not exists profiles_manager_idx on public.profiles(manager_id); create index if not exists profiles_department_idx on public.profiles(department_id);
create or replace function public.enforce_profile_self_update() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.id=auth.uid() and not public.is_management() then if new.role is distinct from old.role or new.department_id is distinct from old.department_id or new.designation is distinct from old.designation or new.manager_id is distinct from old.manager_id or new.employee_code is distinct from old.employee_code or new.joining_date is distinct from old.joining_date or new.status is distinct from old.status or new.email is distinct from old.email then raise exception 'Employment fields cannot be changed by employees'; end if; end if; return new; end $$;
drop trigger if exists profile_self_update_guard on public.profiles; create trigger profile_self_update_guard before update on public.profiles for each row execute function public.enforce_profile_self_update();
insert into storage.buckets(id,name,public) values('profile-photos','profile-photos',false) on conflict(id) do nothing;
drop policy if exists "profile photo upload" on storage.objects; create policy "profile photo upload" on storage.objects for insert to authenticated with check(bucket_id='profile-photos' and owner_id=auth.uid()::text and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "profile photo view" on storage.objects; create policy "profile photo view" on storage.objects for select to authenticated using(bucket_id='profile-photos' and (owner_id=auth.uid()::text or public.is_management()));
